import csv
refs = {
 "CHWPump02":"a39e93e1-f68f-5e9e-b836-56293fd89fa7",
 "Chiller02":"6041ce4e-9251-5a23-9103-a13dcc247d28",
 "SupplyFan_AHU01":"4693f367-6f23-5b26-868f-f17e866f28b6"
}
day="2018-07-19"
totals={}
for name,tsid in refs.items():
    tot=0.0
    n=0
    with open(VALUES_CSV) as f:
        rd=csv.DictReader(f)
        for row in rd:
            if row["timeseries_id"]==tsid and row["timestamp"].startswith(day):
                try:
                    v=float(row["value"])
                except:
                    continue
                tot+=v
                n+=1
    totals[name]=(tot,n)
print(totals)
print(max(totals,key=lambda k:totals[k][0]))
